"""Builds data/sources.json — the machine-readable source registry for HomeKeeper.

Every entry traces back to audit/tracks/*.md (audited 2026-10-29). Fields:
  id, track, publisher, name, url, kind, coverage, access, point_query,
  license, permitted_use, automated_access, verification, decision,
  supports, limitations, checked
`verification`: live_verified | documented | unverified
`decision`: integrate | integrate_manual | link_only | defer | omit
`permitted_use`: redistribute | attribute | paraphrase_attribute | link_only | paid
"""
import json, pathlib

CHECKED = "2026-10-29"

def S(id, track, publisher, name, url, kind, coverage, access, point_query, license,
      permitted_use, automated_access, verification, decision, supports, limitations):
    return dict(id=id, track=track, publisher=publisher, name=name, url=url, kind=kind,
                coverage=coverage, access=access, point_query=point_query, license=license,
                permitted_use=permitted_use, automated_access=automated_access,
                verification=verification, decision=decision, supports=supports,
                limitations=limitations, checked=CHECKED)

